import{_ as t,c as e,o as a,a0 as o}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Goal Setting & Tracking Template","description":"","frontmatter":{},"headers":[],"relativePath":"en/goal-template.md","filePath":"en/goal-template.md"}');const i=t({name:"en/goal-template.md"},[["render",function(t,r,i,l,n,s){return a(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="goal-setting-tracking-template" tabindex="-1">Goal Setting &amp; Tracking Template <a class="header-anchor" href="#goal-setting-tracking-template" aria-label="Permalink to &quot;Goal Setting &amp; Tracking Template&quot;">​</a></h1><h2 id="how-to-use-this-template" tabindex="-1">How to Use This Template <a class="header-anchor" href="#how-to-use-this-template" aria-label="Permalink to &quot;How to Use This Template&quot;">​</a></h2><p>This template helps you set meaningful goals and track your progress systematically. Use the templates below directly on this page, or copy them to your preferred digital tool.</p><div class="tip custom-block"><p class="custom-block-title">The Goal-Setting Philosophy</p><p><strong>Goals without tracking are just wishes. Tracking without reflection is just data.</strong> This template combines both: clear goal-setting with structured reflection to ensure continuous improvement.</p></div><h2 id="quick-access" tabindex="-1">Quick Access <a class="header-anchor" href="#quick-access" aria-label="Permalink to &quot;Quick Access&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Template</th><th>Purpose</th><th>Access</th></tr></thead><tbody><tr><td><strong>Annual Goal Setting</strong></td><td>Set yearly goals across all areas</td><td><a href="#annual-goal-setting-template">View Template</a></td></tr><tr><td><strong>Quarterly Review</strong></td><td>Track progress every 3 months</td><td><a href="#quarterly-review-template">View Template</a></td></tr><tr><td><strong>Monthly Check-In</strong></td><td>Monthly progress assessment</td><td><a href="#monthly-check-in-template">View Template</a></td></tr><tr><td><strong>Weekly Planning</strong></td><td>Plan your weekly training focus</td><td><a href="#weekly-planning-template">View Template</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Digital-First Approach</p><p>All templates are available on this page for easy access on any device. Bookmark this page and use it directly, or copy sections to your preferred note-taking app.</p></div><h2 id="annual-goal-setting-template" tabindex="-1">Annual Goal Setting Template <a class="header-anchor" href="#annual-goal-setting-template" aria-label="Permalink to &quot;Annual Goal Setting Template&quot;">​</a></h2><h3 id="copy-this-section-to-your-document" tabindex="-1">Copy This Section to Your Document <a class="header-anchor" href="#copy-this-section-to-your-document" aria-label="Permalink to &quot;Copy This Section to Your Document&quot;">​</a></h3><hr><p><strong>Year:</strong> ________</p><p><strong>My Pétanque Vision for This Year:</strong></p><p>(In one sentence, what do I want to achieve this year?)</p><hr><h3 id="_1-competition-goals" tabindex="-1">1. Competition Goals <a class="header-anchor" href="#_1-competition-goals" aria-label="Permalink to &quot;1. Competition Goals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Goal Type</th><th>Specific Goal</th><th>Why This Matters</th><th>Success Metric</th></tr></thead><tbody><tr><td><strong>Tournament Results</strong></td><td>Example: Top 8 in Regional Championship</td><td>To prove I can compete at regional level</td><td>Placement in top 8</td></tr><tr><td><strong>Ranking</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Consistency</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Team Performance</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_2-technical-goals" tabindex="-1">2. Technical Goals <a class="header-anchor" href="#_2-technical-goals" aria-label="Permalink to &quot;2. Technical Goals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill Area</th><th>Current Level (1-10)</th><th>Target Level</th><th>Specific Focus</th></tr></thead><tbody><tr><td><strong>Pointing Accuracy</strong></td><td></td><td></td><td>Example: 70% within 10cm at 7m</td></tr><tr><td><strong>Shooting Consistency</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Terrain Adaptation</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Shot Selection</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_3-mental-game-goals" tabindex="-1">3. Mental Game Goals <a class="header-anchor" href="#_3-mental-game-goals" aria-label="Permalink to &quot;3. Mental Game Goals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>Current State</th><th>Target State</th><th>Practice Method</th></tr></thead><tbody><tr><td><strong>Pressure Management</strong></td><td></td><td></td><td>Example: Use 3-breath reset before every shot</td></tr><tr><td><strong>Inner Critic</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Focus/Concentration</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Confidence</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_4-physical-goals" tabindex="-1">4. Physical Goals <a class="header-anchor" href="#_4-physical-goals" aria-label="Permalink to &quot;4. Physical Goals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>Current</th><th>Target</th><th>Action Plan</th></tr></thead><tbody><tr><td><strong>Fitness Level</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Flexibility</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Endurance</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Injury Prevention</strong></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="quarterly-review-template" tabindex="-1">Quarterly Review Template <a class="header-anchor" href="#quarterly-review-template" aria-label="Permalink to &quot;Quarterly Review Template&quot;">​</a></h2><h3 id="copy-this-section-every-3-months" tabindex="-1">Copy This Section Every 3 Months <a class="header-anchor" href="#copy-this-section-every-3-months" aria-label="Permalink to &quot;Copy This Section Every 3 Months&quot;">​</a></h3><hr><p><strong>Quarter:</strong> Q1 / Q2 / Q3 / Q4 <strong>Review Date:</strong> ________</p><h3 id="what-went-well" tabindex="-1">What Went Well? <a class="header-anchor" href="#what-went-well" aria-label="Permalink to &quot;What Went Well?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="what-didn-t-go-as-planned" tabindex="-1">What Didn&#39;t Go As Planned? <a class="header-anchor" href="#what-didn-t-go-as-planned" aria-label="Permalink to &quot;What Didn&#39;t Go As Planned?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="key-learnings" tabindex="-1">Key Learnings <a class="header-anchor" href="#key-learnings" aria-label="Permalink to &quot;Key Learnings&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="adjustments-for-next-quarter" tabindex="-1">Adjustments for Next Quarter <a class="header-anchor" href="#adjustments-for-next-quarter" aria-label="Permalink to &quot;Adjustments for Next Quarter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Goal Area</th><th>Original Goal</th><th>Adjustment Needed</th><th>New Target</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="monthly-goal-template" tabindex="-1">Monthly Goal Template <a class="header-anchor" href="#monthly-goal-template" aria-label="Permalink to &quot;Monthly Goal Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Month:</strong> ________ <strong>Year:</strong> ________</p><h3 id="this-month-s-focus" tabindex="-1">This Month&#39;s Focus <a class="header-anchor" href="#this-month-s-focus" aria-label="Permalink to &quot;This Month&#39;s Focus&quot;">​</a></h3><p><strong>Primary Goal:</strong></p><p><strong>Why This Month:</strong></p><h3 id="weekly-breakdown" tabindex="-1">Weekly Breakdown <a class="header-anchor" href="#weekly-breakdown" aria-label="Permalink to &quot;Weekly Breakdown&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Week</th><th>Specific Target</th><th>Training Focus</th><th>Competition/Test</th></tr></thead><tbody><tr><td><strong>Week 1</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Week 2</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Week 3</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Week 4</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="monthly-metrics-to-track" tabindex="-1">Monthly Metrics to Track <a class="header-anchor" href="#monthly-metrics-to-track" aria-label="Permalink to &quot;Monthly Metrics to Track&quot;">​</a></h3><ul><li>[ ] Training sessions completed: _____ / _____</li><li>[ ] Competitions entered: _____ / _____</li><li>[ ] Mental training practice: _____ days</li><li>[ ] Physical conditioning: _____ sessions</li><li>[ ] Reflection/journaling: _____ entries</li></ul><hr><h2 id="weekly-planning-template" tabindex="-1">Weekly Planning Template <a class="header-anchor" href="#weekly-planning-template" aria-label="Permalink to &quot;Weekly Planning Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Week of:</strong> ________</p><h3 id="this-week-s-intention" tabindex="-1">This Week&#39;s Intention <a class="header-anchor" href="#this-week-s-intention" aria-label="Permalink to &quot;This Week&#39;s Intention&quot;">​</a></h3><p>(What is my one main focus this week?)</p><h3 id="training-schedule" tabindex="-1">Training Schedule <a class="header-anchor" href="#training-schedule" aria-label="Permalink to &quot;Training Schedule&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Day</th><th>Activity</th><th>Duration</th><th>Focus Area</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Monday</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Tuesday</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Wednesday</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Thursday</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Friday</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Saturday</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Sunday</strong></td><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="weekly-targets" tabindex="-1">Weekly Targets <a class="header-anchor" href="#weekly-targets" aria-label="Permalink to &quot;Weekly Targets&quot;">​</a></h3><ul><li>[ ] Technical practice: _____ hours</li><li>[ ] Competition/match play: _____ hours</li><li>[ ] Mental training: _____ minutes</li><li>[ ] Physical training: _____ sessions</li><li>[ ] Video analysis: _____ sessions</li></ul><hr><h2 id="progress-tracking-sheet" tabindex="-1">Progress Tracking Sheet <a class="header-anchor" href="#progress-tracking-sheet" aria-label="Permalink to &quot;Progress Tracking Sheet&quot;">​</a></h2><h3 id="copy-this-to-excel-google-sheets" tabindex="-1">Copy This to Excel/Google Sheets <a class="header-anchor" href="#copy-this-to-excel-google-sheets" aria-label="Permalink to &quot;Copy This to Excel/Google Sheets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Goal Area</th><th>Target</th><th>Actual</th><th>Notes</th><th>Feeling (1-10)</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions for Spreadsheet:</strong></p><ol><li>Create columns: Date, Goal Area, Target, Actual, Notes, Feeling</li><li>Add new row after each training session or competition</li><li>Use conditional formatting: Green if Actual ≥ Target, Yellow if close, Red if far off</li><li>Create charts to visualize progress over time</li></ol><hr><h2 id="competition-performance-tracker" tabindex="-1">Competition Performance Tracker <a class="header-anchor" href="#competition-performance-tracker" aria-label="Permalink to &quot;Competition Performance Tracker&quot;">​</a></h2><h3 id="copy-this-to-track-tournament-results" tabindex="-1">Copy This to Track Tournament Results <a class="header-anchor" href="#copy-this-to-track-tournament-results" aria-label="Permalink to &quot;Copy This to Track Tournament Results&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Tournament</th><th>Round Reached</th><th>Placement</th><th>Key Strengths</th><th>Areas to Improve</th><th>Mental State (1-10)</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="goal-achievement-celebration" tabindex="-1">Goal Achievement Celebration <a class="header-anchor" href="#goal-achievement-celebration" aria-label="Permalink to &quot;Goal Achievement Celebration&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Celebrate Progress!</p><p><strong>Every goal achieved deserves recognition.</strong> When you hit a target:</p><ol><li>✅ Mark it complete</li><li>🎉 Acknowledge the effort it took</li><li>📝 Write what you learned</li><li>🎯 Set the next challenge</li></ol></div><h3 id="achievement-log" tabindex="-1">Achievement Log <a class="header-anchor" href="#achievement-log" aria-label="Permalink to &quot;Achievement Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Goal Achieved</th><th>What It Took</th><th>Key Learning</th><th>Next Challenge</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="tips-for-effective-goal-setting" tabindex="-1">Tips for Effective Goal Setting <a class="header-anchor" href="#tips-for-effective-goal-setting" aria-label="Permalink to &quot;Tips for Effective Goal Setting&quot;">​</a></h2><h3 id="_1-start-small-build-momentum" tabindex="-1">1. Start Small, Build Momentum <a class="header-anchor" href="#_1-start-small-build-momentum" aria-label="Permalink to &quot;1. Start Small, Build Momentum&quot;">​</a></h3><p>Don&#39;t set 20 goals at once. Start with:</p><ul><li><strong>1 competition goal</strong></li><li><strong>1 technical goal</strong></li><li><strong>1 mental game goal</strong></li></ul><p>Master tracking these before adding more.</p><h3 id="_2-review-regularly" tabindex="-1">2. Review Regularly <a class="header-anchor" href="#_2-review-regularly" aria-label="Permalink to &quot;2. Review Regularly&quot;">​</a></h3><ul><li><strong>Daily:</strong> Check today&#39;s intention</li><li><strong>Weekly:</strong> Review week&#39;s progress, plan next week</li><li><strong>Monthly:</strong> Assess monthly targets, adjust if needed</li><li><strong>Quarterly:</strong> Deep reflection, major adjustments</li><li><strong>Annually:</strong> Celebrate year, set new vision</li></ul><h3 id="_3-be-honest-not-harsh" tabindex="-1">3. Be Honest, Not Harsh <a class="header-anchor" href="#_3-be-honest-not-harsh" aria-label="Permalink to &quot;3. Be Honest, Not Harsh&quot;">​</a></h3><p>When you miss a target:</p><ul><li>❌ <strong>Don&#39;t:</strong> &quot;I&#39;m terrible, I&#39;ll never improve&quot;</li><li>✅ <strong>Do:</strong> &quot;What got in the way? What can I adjust?&quot;</li></ul><h3 id="_4-link-goals-to-your-why" tabindex="-1">4. Link Goals to Your Why <a class="header-anchor" href="#_4-link-goals-to-your-why" aria-label="Permalink to &quot;4. Link Goals to Your Why&quot;">​</a></h3><p>Every goal should connect to your deeper motivation:</p><ul><li>Why do you play pétanque?</li><li>What does improvement mean to you?</li><li>How will achieving this goal feel?</li></ul><h3 id="_5-make-it-visible" tabindex="-1">5. Make It Visible <a class="header-anchor" href="#_5-make-it-visible" aria-label="Permalink to &quot;5. Make It Visible&quot;">​</a></h3><ul><li>Print your annual goals and post them where you see them daily</li><li>Set phone reminders for weekly reviews</li><li>Share goals with your training partner for accountability</li></ul><hr><h2 id="digital-vs-paper-tracking" tabindex="-1">Digital vs. Paper Tracking <a class="header-anchor" href="#digital-vs-paper-tracking" aria-label="Permalink to &quot;Digital vs. Paper Tracking&quot;">​</a></h2><h3 id="digital-google-sheets-excel" tabindex="-1">Digital (Google Sheets/Excel) <a class="header-anchor" href="#digital-google-sheets-excel" aria-label="Permalink to &quot;Digital (Google Sheets/Excel)&quot;">​</a></h3><p><strong>Pros:</strong></p><ul><li>Easy to update anywhere</li><li>Automatic calculations and charts</li><li>Can share with coach/training partner</li><li>Search and filter data</li></ul><p><strong>Cons:</strong></p><ul><li>Requires device</li><li>Can feel impersonal</li><li>Easy to ignore notifications</li></ul><h3 id="paper-notebook-printed-templates" tabindex="-1">Paper (Notebook/Printed Templates) <a class="header-anchor" href="#paper-notebook-printed-templates" aria-label="Permalink to &quot;Paper (Notebook/Printed Templates)&quot;">​</a></h3><p><strong>Pros:</strong></p><ul><li>Tactile, personal connection</li><li>No distractions</li><li>Easy to review during training</li><li>Satisfying to check boxes</li></ul><p><strong>Cons:</strong></p><ul><li>Can&#39;t easily create charts</li><li>Risk of losing notebook</li><li>Harder to share</li></ul><p><strong>Recommendation:</strong> Use both! Digital for data tracking, paper for daily intentions and reflections.</p><hr><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/en/workshop">Workshop</a> - Group sessions on goal setting and mental game</li><li><a href="/en/training-session">Training Session</a> - Practice with accountability partners</li><li><a href="/en/education/mental-strength">Mental Strength</a> - Build the mindset for goal achievement</li><li><a href="/en/diary-template">Training Diary Template</a> - Daily practice tracking</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to goal setting? Start here:</strong></p><ol><li><strong>Week 1:</strong> Set ONE monthly goal using SMART framework</li><li><strong>Week 2:</strong> Track daily progress in simple table</li><li><strong>Week 3:</strong> Do first weekly review</li><li><strong>Week 4:</strong> Adjust goal if needed, celebrate progress</li></ol><p><strong>After one month:</strong> Add quarterly and annual goals.</p><hr><div class="warning custom-block"><p class="custom-block-title">Common Goal-Setting Mistakes</p><ol><li><strong>Too many goals</strong> - Focus is diluted</li><li><strong>Too vague</strong> - &quot;Get better&quot; isn&#39;t measurable</li><li><strong>No tracking</strong> - Can&#39;t see progress</li><li><strong>No review</strong> - Miss opportunities to adjust</li><li><strong>All outcome, no process</strong> - Focus on what you can control</li></ol></div><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Annual Goal Setting Template</li><li>Weekly Planning Template</li><li>Progress Tracking Sheet</li></ol><hr><p>Use this framework to make your goals specific and achievable:</p><h3 id="smart-goal-template" tabindex="-1">SMART Goal Template <a class="header-anchor" href="#smart-goal-template" aria-label="Permalink to &quot;SMART Goal Template&quot;">​</a></h3><p><strong>S - Specific:</strong> (What exactly do I want to achieve?)</p><p><strong>M - Measurable:</strong> (How will I know I&#39;ve achieved it?)</p><p><strong>A - Achievable:</strong> (Is this realistic given my current level and resources?)</p><p><strong>R - Relevant:</strong> (Why does this matter to my overall vision?)</p><p><strong>T - Time-bound:</strong> (By when will I achieve this?)</p><h3 id="example-smart-goals" tabindex="-1">Example SMART Goals <a class="header-anchor" href="#example-smart-goals" aria-label="Permalink to &quot;Example SMART Goals&quot;">​</a></h3><details class="details custom-block"><summary>Example 1: Technical Goal</summary><p><strong>S - Specific:</strong> Improve pointing accuracy on hard terrain <strong>M - Measurable:</strong> Land within 20cm of cochonnet 7 out of 10 attempts <strong>A - Achievable:</strong> Currently at 4/10, so 7/10 is challenging but realistic <strong>R - Relevant:</strong> Hard terrain is common in regional tournaments <strong>T - Time-bound:</strong> Achieve by end of Q2 (June 30)</p></details><details class="details custom-block"><summary>Example 2: Competition Goal</summary><p><strong>S - Specific:</strong> Reach semi-finals in Club Championship <strong>M - Measurable:</strong> Finish in top 4 of 32-player tournament <strong>A - Achievable:</strong> Currently ranked 8-12 in club, improvement is realistic <strong>R - Relevant:</strong> Builds confidence and proves progress <strong>T - Time-bound:</strong> Championship is September 15</p></details><details class="details custom-block"><summary>Example 3: Mental Game Goal</summary><p><strong>S - Specific:</strong> Manage inner critic during competition <strong>M - Measurable:</strong> Use Inner Coach reframe after every miss <strong>A - Achievable:</strong> Have practiced technique in training <strong>R - Relevant:</strong> Negative self-talk is my biggest barrier <strong>T - Time-bound:</strong> Consistent use in next 3 tournaments</p></details><hr>',130)])])}]]);export{r as __pageData,i as default};
